    public static JSONObject pipeIdentityForHost(JSONObject scope)throws Exception{JSONObject p=scope.getJSONObject("program");return new JSONObject().put("purpose",INTENT).put("installationId",p.getString("installationId")).put("stateRevision",p.getLong("stateRevision")).put("configDigest",p.getString("configurationDigest")).put("runtimeGeneration",p.getString("runtimeIdentity"));}
